int[][] merge(int[][] a) {
  Arrays.sort(a, (x, y) -> Integer.compare(x[0], y[0]));
  List<int[]> r = new ArrayList<>();
  for (int[] cur : a) {
    if (r.isEmpty() || r.get(r.size() - 1)[1] < cur[0]) r.add(cur);
    else r.get(r.size() - 1)[1] = Math.max(r.get(r.size() - 1)[1], cur[1]);
  }
  return r.toArray(new int[0][]);
}

int lengthOfLongest(String s) {
  Map<Character,Integer> last = new HashMap<>();
  int best = 0, l = 0;
  for (int r = 0; r < s.length(); r++) {
    char c = s.charAt(r);
    if (last.containsKey(c) && last.get(c) >= l) l = last.get(c) + 1;
    last.put(c, r);
    best = Math.max(best, r - l + 1);
  }
  return best;
}

boolean isAnagram(String a, String b) {
  if (a.length() != b.length()) return false;
  int[] c = new int[26];
  for (int i = 0; i < a.length(); i++) {
    c[a.charAt(i) - 'a']++;
    c[b.charAt(i) - 'a']--;
  }
  for (int x : c) if (x != 0) return false;
  return true;
}

List<List<String>> group(String[] w) {
  Map<String,List<String>> m = new HashMap<>();
