class OddEven {
  private int n = 1;
  private final int max = 10;
  synchronized void print(boolean odd) {
    while (n <= max) {
      if ((n % 2 == 1) == odd) { System.out.println(n++); notifyAll(); }
      else { try { wait(); } catch (InterruptedException e) { return; } }
    }
    notifyAll();
  }
}
